static boolean lastTrialDay(Account account) {
    LocalDate ends = account.trialStarted().toLocalDate().plusDays(14);   // trialStarted() is a LocalDateTime
    if (account.extended()) {
        ends.plusDays(7);
    }
    return LocalDate.now().equals(ends);
}

